fun main() {
    val a: UInt = 4_000_000_000u
    val b: UInt = 500_000_000u
    println(a + b)
    println(a - b)
    println(b - a)
    println(a * 2u)
    println(a / 7u)
    println(a % 7u)
    println(UInt.MAX_VALUE)
    println(UInt.MIN_VALUE)
    val l: ULong = 18_000_000_000_000_000_000uL
    println(l + l)
    println(l / 3uL)
    println(ULong.MAX_VALUE)
    println(l.toString(16))
    println(255.toUByte())
    println((200u).toUByte() + (100u).toUByte())
    println(65535.toUShort())
    println(a.toInt())
    println((-1).toUInt())
    println(a.toLong())
    println(a > b)
    println(1u shl 31)
    println(0xFFu and 0x0Fu)
    println(a.toULong() * 4u)
    println(3u.toDouble() / 2)
    println(ULong.MAX_VALUE.toDouble())
    println(listOf(3u, 1u, 2u).sorted())
    println((10u..15u).toList())
    println(UInt.MAX_VALUE.inv())
    println(5u.compareTo(7u))
    println("42".toUInt() + 1u)
    println(ubyteArrayOf(1u, 2u).sumOf { it.toInt() })
}
